function NavBar({ page, setPage }) {
  const [open, setOpen] = useState(false);
  const go = (id) => {
    setPage(id);
    setOpen(false);
    window.scrollTo({ top: 0, behavior: "instant" in window ? "instant" : "auto" });
  };
  return (
    <header className="nav-shell">
      <nav className="nav-inner">
        <button className="brand" onClick={() => go("home")}>
          <img className="brand-logo" src={IMG.logo} alt="Senator Adams Foundation" />
        </button>

        <div className="nav-links">
          {PAGES.map((p) => (
            <button
              key={p.id}
              className={"nav-link" + (page === p.id ? " active" : "")}
              onClick={() => go(p.id)}
            >
              {p.label}
            </button>
          ))}
          <button
            className={"nav-cta" + (page === "senator" ? " active" : "")}
            onClick={() => go("senator")}
          >
            {SENATOR_PAGE.label}
          </button>
        </div>

        <button className="hamburger" aria-label="Menu" onClick={() => setOpen((o) => !o)}>
          {open ? <X size={22} /> : <Menu size={22} />}
        </button>
      </nav>

      <div className={"nav-mobile" + (open ? " open" : "")}>
        {[...PAGES, SENATOR_PAGE].map((p) => (
          <button
            key={p.id}
            className={
              "nav-mobile-link" +
              (page === p.id ? " active" : "") +
              (p.id === "senator" ? " gold" : "")
            }
            onClick={() => go(p.id)}
          >
            {p.label}
            <ChevronRight size={16} />
          </button>
        ))}
      </div>
    </header>
  );
}

/* ============================================================
   MOTION HERO (Home page)
   ============================================================ */
function MotionHero({ setPage }) {
  const wrapRef = useRef(null);
  const [progress, setProgress] = useState(0);
  const reduced = useRef(prefersReducedMotion());

  useEffect(() => {
    if (reduced.current) {
      setProgress(1);
      return;
    }
    let raf = null;
    const onScroll = () => {
      if (raf) return;
      raf = requestAnimationFrame(() => {
        raf = null;
        const el = wrapRef.current;
        if (!el) return;
        const rect = el.getBoundingClientRect();
        const total = el.offsetHeight - window.innerHeight;
        const scrolled = -rect.top;
        const p = clamp(scrolled / Math.max(total, 1), 0, 1);
        setProgress(p);
      });
    };
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", onScroll);
    return () => {
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", onScroll);
    };
  }, []);

  // Phase math
  const p1 = clamp(progress / 0.3, 0, 1); // portrait reveal
  const p2 = clamp((progress - 0.3) / 0.3, 0, 1); // text transition
  const p3 = clamp((progress - 0.6) / 0.4, 0, 1); // CTA convergence

  const imgScale = lerp(1.08, 0.86, p1) - lerp(0, 0.18, p3);
  const imgTranslateX = lerp(0, -18, p3);
  const imgTranslateY = lerp(30, 0, p1);
  const imgClip = lerp(18, 2, p1);

  const textOpacity = p2;
  const textTranslate = lerp(36, 0, p2);

  const ctaOpacity = p3;
  const ctaTranslate = lerp(24, 0, p3);

  return (
    <div ref={wrapRef} className="hero-wrap">
      <div className="hero-sticky">
        <div className="hero-bg" />
        <div className="hero-grid">
          <div
            className="hero-portrait"
            style={{
              transform: `translate(${imgTranslateX}%, ${imgTranslateY}px) scale(${imgScale})`,
              clipPath: `polygon(${imgClip}% 0%, 100% 0%, ${100 - imgClip * 0.4}% 100%, 0% 100%)`,
            }}
          >
            <img src={IMG.hero} alt="Adams Mochenwa, Founder of the Bwatesia Mochenwa Foundation" />
            <div className="hero-portrait-frame" />
          </div>

          <div
            className="hero-copy"
            style={{
              opacity: textOpacity,
              transform: `translateY(${textTranslate}px)`,
            }}
          >
            <p className="hero-eyebrow">
              Bwatesia Mochenwa Foundation <span className="dot">·</span> Nyamira County
            </p>
            <h1>Sukuma Nyamira Mbele, Kubadilisha Maisha Yetu.</h1>
            <p className="hero-sub">
              The Bwatesia Mochenwa Foundation drives long-term community development through
              grassroots infrastructure restoration, urgent humanitarian relief, and youth peace
              advocacy.
            </p>

            <div
              className="hero-cta-row"
              style={{
                opacity: ctaOpacity,
                transform: `translateY(${ctaTranslate}px)`,
                pointerEvents: ctaOpacity > 0.5 ? "auto" : "none",
              }}
            >
              <button className="btn btn-gold" onClick={() => setPage("senator")}>
                Partner With Us <ArrowRight size={16} />
              </button>
              <button className="btn btn-outline" onClick={() => setPage("projects")}>
                Explore Our Impact
              </button>
            </div>
          </div>
        </div>

        <div className="hero-scroll-hint" style={{ opacity: 1 - p1 }}>
          <span>Scroll</span>
          <div className="hero-scroll-line" />
        </div>
      </div>
    </div>
  );
}

