function ImpactCard({ stat }) {
  const [ref, inView] = useInView(0.4);
  const val = useCountUp(stat.value, inView);
  const Icon = stat.icon;
  return (
    <div className="bento-card" ref={ref}>
      <Icon size={22} className="bento-icon" />
      <div className="bento-number">
        {val}
        {stat.suffix}
      </div>
      <p className="bento-label">{stat.label}</p>
    </div>
  );
}

function ImpactDashboard() {
  return (
    <section className="section">
      <div className="section-head">
        <p className="kicker">Lifetime impact</p>
        <h2>What community-first funding has already built</h2>
      </div>
      <div className="bento-grid">
        {IMPACT_STATS.map((s, i) => (
          <ImpactCard stat={s} key={i} />
        ))}
      </div>
    </section>
  );
}

