/* ============================================================
   SHARED FORM HELPER
   ============================================================ */
function useFormState(initial) {
  const [values, setValues] = useState(initial);
  const [errors, setErrors] = useState({});
  const set = (k, v) => setValues((s) => ({ ...s, [k]: v }));
  return { values, set, errors, setErrors };
}

