/* ============================================================
   APP
   ============================================================ */
export default function App() {
  const [page, setPage] = useState("home");
  const [toast, setToast] = useState(null);

  const showToast = useCallback((msg) => {
    setToast(msg);
    window.clearTimeout(showToast._t);
    showToast._t = window.setTimeout(() => setToast(null), 3600);
  }, []);

  let PageComp;
  if (page === "home") PageComp = <HomePage setPage={setPage} />;
  else if (page === "about") PageComp = <AboutPage />;
  else if (page === "projects") PageComp = <ProjectsPage />;
  else if (page === "gallery") PageComp = <GalleryPage />;
  else if (page === "news") PageComp = <NewsPage />;
  else if (page === "senator") PageComp = <SenatorPage />;

  return (
    <ToastCtx.Provider value={showToast}>
      <div className="app-root">
        <style>{CSS}</style>
        <NavBar page={page} setPage={setPage} />
        <main>{PageComp}</main>
        <Footer setPage={setPage} />
        <ToastHost toast={toast} />
      </div>
    </ToastCtx.Provider>
  );
}

/* ============================================================
   STYLES
   ============================================================ */
const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=Work+Sans:wght@400;500;600;700&display=swap');

:root{
  --emerald-950:#0B2A20;
  --emerald-800:#0F3D2E;
  --emerald-700:#155C43;
  --emerald-600:#1C6B4E;
  --gold-600:#B8862D;
  --gold-500:#CC9A3D;
  --gold-100:#F3E6C8;
  --paper:#F7F6F1;
  --paper-dim:#EEEBE1;
  --charcoal:#191B18;
  --charcoal-60:rgba(25,27,24,.62);
  --line:rgba(25,27,24,.12);
  --radius-s:6px;
  --radius-m:14px;
}

*{box-sizing:border-box;}
.app-root{font-family:'Work Sans',sans-serif;color:var(--charcoal);background:var(--paper);}
.app-root h1,.app-root h2,.app-root h3,.app-root h4{font-family:'Plus Jakarta Sans',sans-serif;font-weight:700;color:var(--emerald-950);line-height:1.12;margin:0;}
.app-root p{margin:0;line-height:1.6;color:var(--charcoal-60);}
button{font-family:inherit;cursor:pointer;}
input,select,textarea{font-family:inherit;}
@media (prefers-reduced-motion: reduce){ *{scroll-behavior:auto!important;} }

.kicker.kicker{font-family:'Work Sans',sans-serif;font-size:.85rem;letter-spacing:.02em;color:var(--gold-600);font-weight:600;margin:0 0 .6rem;}
.kicker.gold{color:var(--gold-500);}

/* NAV */
.nav-shell{position:sticky;top:0;z-index:50;backdrop-filter:blur(14px);background:rgba(247,246,241,.78);border-bottom:1px solid var(--line);}
.nav-inner{max-width:1240px;margin:0 auto;display:flex;align-items:center;justify-content:space-between;padding:.85rem 1.5rem;}
.brand{display:flex;align-items:center;gap:.6rem;background:none;border:none;padding:0;}
.brand-logo{height:42px;width:auto;display:block;}
.footer-logo-wrap{display:inline-block;background:var(--paper);padding:.7rem 1.1rem;border-radius:var(--radius-m);margin-bottom:1.1rem;}
.footer-logo{height:34px;width:auto;display:block;}
.nav-links{display:none;align-items:center;gap:1.6rem;}
.nav-link{background:none;border:none;font-size:.92rem;color:var(--charcoal-60);padding:.3rem 0;border-bottom:2px solid transparent;}
.nav-link.active{color:var(--emerald-800);border-color:var(--emerald-700);}
.nav-cta{background:none;border:1.5px solid var(--gold-600);color:var(--gold-600);border-radius:999px;padding:.45rem 1rem;font-size:.86rem;font-weight:600;}
.nav-cta.active{background:var(--gold-600);color:#fff;}
.hamburger{background:none;border:none;color:var(--emerald-950);}
.nav-mobile{max-height:0;overflow:hidden;transition:max-height .35s ease;background:var(--paper);border-bottom:1px solid var(--line);}
.nav-mobile.open{max-height:420px;}
.nav-mobile-link{display:flex;width:100%;justify-content:space-between;align-items:center;background:none;border:none;border-top:1px solid var(--line);padding:.9rem 1.5rem;font-size:.95rem;color:var(--charcoal);text-align:left;}
.nav-mobile-link.active{color:var(--emerald-700);font-weight:600;}
.nav-mobile-link.gold{color:var(--gold-600);font-weight:600;}
@media(min-width:960px){ .nav-links{display:flex;} .hamburger{display:none;} .nav-mobile{display:none;} }

/* HERO */
.hero-wrap{height:300vh;position:relative;}
.hero-sticky{position:sticky;top:0;height:100vh;overflow:hidden;background:linear-gradient(180deg,var(--emerald-950),var(--emerald-800));}
.hero-bg{position:absolute;inset:0;background:radial-gradient(circle at 75% 20%, rgba(204,154,61,.18), transparent 55%);}
.hero-grid{position:relative;z-index:2;max-width:1240px;margin:0 auto;height:100%;display:grid;grid-template-columns:1fr;align-items:center;gap:1rem;padding:3.5rem 1.5rem;}
.hero-portrait{width:min(78vw,320px);aspect-ratio:3/4;margin:0 auto;position:relative;overflow:hidden;justify-self:center;}
.hero-portrait img{width:100%;height:100%;object-fit:cover;display:block;}
.hero-portrait-frame{position:absolute;inset:0;border:1.5px solid rgba(204,154,61,.55);pointer-events:none;}
.hero-copy{color:#F7F6F1;text-align:center;max-width:640px;margin:1.5rem auto 0;}
.hero-copy h1{color:var(--gold-500);font-size:clamp(1.9rem,5vw,3.1rem);margin:.5rem 0 1rem;}
.hero-copy .hero-eyebrow{color:#FFFFFF;font-size:.85rem;letter-spacing:.03em;font-weight:600;}
.hero-copy .hero-eyebrow .dot{color:var(--gold-500);}
.hero-copy .hero-sub{color:#FFFFFF;font-size:1.02rem;max-width:520px;margin:0 auto;}
.hero-cta-row{display:flex;gap:.9rem;justify-content:center;flex-wrap:wrap;margin-top:2.4rem;padding-bottom:1.2rem;}
.hero-scroll-hint{position:absolute;bottom:28px;left:50%;transform:translateX(-50%);display:flex;flex-direction:column;align-items:center;gap:.4rem;color:rgba(247,246,241,.6);font-size:.72rem;letter-spacing:.08em;}
.hero-scroll-line{width:1px;height:30px;background:linear-gradient(180deg,rgba(247,246,241,.7),transparent);}
@media(min-width:900px){
  .hero-grid{grid-template-columns:.9fr 1.1fr;text-align:left;}
  .hero-portrait{justify-self:start;width:340px;}
  .hero-copy{text-align:left;margin:0;}
  .hero-cta-row{justify-content:flex-start;}
  .hero-sub{margin:0;}
}

/* BUTTONS */
.btn{display:inline-flex;align-items:center;gap:.5rem;border-radius:999px;padding:.85rem 1.6rem;font-size:.92rem;font-weight:600;border:1.5px solid transparent;transition:transform .18s ease, opacity .18s ease;}
.btn:hover{transform:translateY(-1px);}
.btn.full{width:100%;justify-content:center;}
.btn-gold{background:var(--gold-600);color:#fff;}
.btn-gold:hover{background:var(--gold-500);}
.btn-outline{border-color:rgba(247,246,241,.55);color:#F7F6F1;background:transparent;}
.hero-sticky .btn-outline{color:#F7F6F1;}
.page-pad .btn-outline{border-color:var(--emerald-700);color:var(--emerald-800);}
.btn:disabled{opacity:.7;cursor:default;}
.spin{animation:spin 1s linear infinite;}
@keyframes spin{to{transform:rotate(360deg);}}

/* SECTIONS */
.section{max-width:1180px;margin:0 auto;padding:5rem 1.5rem;}
.section-head{max-width:640px;margin-bottom:2.4rem;}
.section-head h2{font-size:clamp(1.5rem,3vw,2.1rem);}
.page-pad{padding-top:1rem;}

/* BENTO / IMPACT */
.bento-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:1.1rem;}
@media(min-width:800px){.bento-grid{grid-template-columns:repeat(4,1fr);}}
.bento-card{background:#fff;border:1px solid var(--line);border-radius:var(--radius-m);padding:1.5rem;transition:border-color .25s ease, box-shadow .25s ease, transform .25s ease;}
.bento-icon{color:var(--gold-600);margin-bottom:.9rem;}
.bento-number{font-family:'Plus Jakarta Sans',sans-serif;font-weight:700;font-size:2.1rem;color:var(--emerald-800);}
.bento-label{font-size:.86rem;margin-top:.5rem;}

/* FOUNDER / SPLIT */
.founder-grid,.split-section{display:grid;grid-template-columns:1fr;gap:2.4rem;align-items:center;}
.founder-image img,.split-image img{width:100%;border-radius:var(--radius-m);display:block;object-fit:cover;aspect-ratio:4/3;}
.founder-copy h2,.split-copy h2{font-size:clamp(1.5rem,3vw,2.1rem);margin-bottom:1rem;}
.founder-copy p,.split-copy p{margin-bottom:1rem;}
.link-cta{display:inline-flex;align-items:center;gap:.4rem;background:none;border:none;color:var(--gold-600);font-weight:600;padding:0;margin-top:.4rem;}
@media(min-width:860px){ .founder-grid,.split-section{grid-template-columns:1fr 1.1fr;} }

/* AGENDA CARDS (About page) */
.agenda-grid{grid-template-columns:1fr;}
@media(min-width:700px){.agenda-grid{grid-template-columns:repeat(2,1fr);}}
.agenda-card h3{font-size:1.08rem;margin:.3rem 0 .6rem;}
.agenda-body{font-size:.9rem;}

/* PROJECTS */
.filter-row{display:flex;gap:.6rem;flex-wrap:wrap;margin-bottom:2rem;}
.filter-chip{border:1px solid var(--line);background:#fff;border-radius:999px;padding:.5rem 1.1rem;font-size:.85rem;color:var(--charcoal-60);}
.filter-chip.active{background:var(--emerald-800);border-color:var(--emerald-800);color:#fff;}
.project-grid{display:grid;grid-template-columns:1fr;gap:1.4rem;}
@media(min-width:760px){.project-grid{grid-template-columns:repeat(2,1fr);}}
@media(min-width:1040px){.project-grid{grid-template-columns:repeat(3,1fr);}}
.project-card{background:#fff;border:1px solid var(--line);border-radius:var(--radius-m);overflow:hidden;transition:border-color .25s ease, box-shadow .25s ease, transform .25s ease;}
.project-image{position:relative;aspect-ratio:4/3;}
.project-image img{width:100%;height:100%;object-fit:cover;display:block;}
.project-tag{position:absolute;top:.8rem;left:.8rem;background:rgba(11,42,32,.85);color:var(--gold-100);font-size:.72rem;padding:.3rem .7rem;border-radius:999px;}
.project-body{padding:1.2rem;}
.project-body h3{font-size:1.05rem;margin-bottom:.5rem;}
.project-body p{font-size:.88rem;}

/* FORMS (Senator volunteer form reuses these) */
.pay-card{background:#fff;border:1px solid var(--line);border-radius:var(--radius-m);padding:1.8rem;max-width:640px;transition:border-color .25s ease, box-shadow .25s ease, transform .25s ease;}
.pay-card.outline{border-color:var(--emerald-700);}
.pay-card-head{display:flex;align-items:center;gap:.7rem;margin-bottom:1.4rem;}
.pay-card-head h3{font-size:1.15rem;}
.pay-badge{background:var(--emerald-800);color:var(--gold-100);font-size:.72rem;padding:.3rem .7rem;border-radius:999px;font-family:'Work Sans',sans-serif;font-weight:600;}
.pay-badge.alt{background:var(--paper-dim);color:var(--emerald-800);}
.pay-badge.gold-badge{background:var(--gold-600);color:#fff;}
.field{display:flex;flex-direction:column;gap:.35rem;margin-bottom:1.1rem;font-size:.85rem;color:var(--charcoal-60);}
.field-row{display:grid;grid-template-columns:1fr;gap:1rem;}
@media(min-width:600px){.field-row{grid-template-columns:1fr 1fr;}}
.field input,.field select,.field textarea{border:1px solid var(--line);border-radius:var(--radius-s);padding:.7rem .85rem;font-size:.94rem;color:var(--charcoal);background:var(--paper);}
.field input:focus,.field select:focus,.field textarea:focus{outline:2px solid var(--emerald-600);outline-offset:1px;}
.error{color:#B3401E;font-size:.78rem;font-style:normal;}
.fine-print{font-size:.76rem;margin-top:.9rem;color:var(--charcoal-60);}
.fine-print.center{text-align:center;margin-bottom:1.6rem;}
.senator-page .fine-print{color:rgba(247,246,241,.72);}

/* GALLERY */
.gallery-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:.9rem;}
@media(min-width:700px){.gallery-grid{grid-template-columns:repeat(3,1fr);}}
@media(min-width:1040px){.gallery-grid{grid-template-columns:repeat(4,1fr);}}
.gallery-item{border-radius:var(--radius-m);overflow:hidden;aspect-ratio:1/1;border:1px solid var(--line);transition:border-color .25s ease, box-shadow .25s ease, transform .25s ease;}
.gallery-item:hover{border-color:var(--gold-500);box-shadow:0 0 0 1px rgba(204,154,61,.4), 0 22px 44px -12px rgba(204,154,61,.35);transform:translateY(-3px);}
.gallery-item img{width:100%;height:100%;object-fit:cover;display:block;}
.video-grid{display:grid;grid-template-columns:1fr;gap:1.2rem;}
@media(min-width:700px){.video-grid{grid-template-columns:repeat(2,1fr);}}
.video-item{position:relative;display:block;border-radius:var(--radius-m);overflow:hidden;aspect-ratio:16/10;border:1px solid var(--line);transition:border-color .25s ease, box-shadow .25s ease, transform .25s ease;}
.video-item:hover{border-color:var(--gold-500);box-shadow:0 0 0 1px rgba(204,154,61,.4), 0 22px 44px -12px rgba(204,154,61,.35);transform:translateY(-3px);}
.video-item img{width:100%;height:100%;object-fit:cover;display:block;}
.video-overlay{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;color:#fff;background:rgba(11,42,32,.28);}
.video-caption{position:absolute;left:0;right:0;bottom:0;padding:.7rem .9rem;background:linear-gradient(0deg,rgba(11,42,32,.85),transparent);color:#fff;font-size:.82rem;display:flex;align-items:center;gap:.4rem;}

/* NEWS */
.news-grid{display:grid;grid-template-columns:1fr;gap:1.4rem;}
@media(min-width:760px){.news-grid{grid-template-columns:repeat(2,1fr);}}
@media(min-width:1040px){.news-grid{grid-template-columns:repeat(3,1fr);}}
.news-date{font-size:.76rem;color:var(--gold-600);font-weight:600;}
.news-card .project-body h3{margin-top:.3rem;}

/* SENATOR PAGE */
.senator-page{background:var(--emerald-950);}
.senator-hero{max-width:1180px;margin:0 auto;padding:4.5rem 1.5rem 3.5rem;display:grid;grid-template-columns:1fr;gap:2.4rem;align-items:center;}
@media(min-width:900px){.senator-hero{grid-template-columns:1.15fr .85fr;}}
.senator-hero-copy h1{color:#fff;font-size:clamp(1.9rem,4vw,2.9rem);margin:.6rem 0 1rem;}
.senator-hero-copy p{color:rgba(247,246,241,.75);font-size:1.02rem;max-width:480px;}
.senator-hero-image{border-radius:var(--radius-m);overflow:hidden;border:1px solid rgba(204,154,61,.4);}
.senator-hero-image img{width:100%;display:block;object-fit:cover;aspect-ratio:4/3;}
.senator-page .section-head h2{color:#fff;}
.senator-page .kicker{color:var(--gold-500);}
.manifesto-grid{display:grid;grid-template-columns:1fr;gap:1.2rem;}
@media(min-width:800px){.manifesto-grid{grid-template-columns:repeat(3,1fr);}}
.manifesto-card{background:rgba(247,246,241,.05);border:1px solid rgba(247,246,241,.15);border-radius:var(--radius-m);padding:1.6rem;color:rgba(247,246,241,.8);transition:border-color .25s ease, box-shadow .25s ease, transform .25s ease;}
.manifesto-card svg{color:var(--gold-500);margin-bottom:.9rem;}
.manifesto-card h3{color:#fff;font-size:1.1rem;margin-bottom:.6rem;}
.manifesto-card p{font-size:.88rem;color:rgba(247,246,241,.7);}
.timeline{display:flex;flex-direction:column;gap:1.4rem;}
.timeline-item{display:flex;gap:1rem;align-items:flex-start;}
.timeline-dot{width:10px;height:10px;border-radius:50%;background:var(--gold-500);margin-top:.35rem;flex-shrink:0;}
.timeline-body h4{color:#fff;font-size:1rem;font-family:'Work Sans',sans-serif;font-weight:600;}
.timeline-body p{color:rgba(247,246,241,.7);font-size:.86rem;margin:.2rem 0;}
.timeline-body span{color:var(--gold-500);font-size:.78rem;}
.senator-form{background:rgba(247,246,241,.06);border:1px solid rgba(247,246,241,.18);max-width:none;}
.senator-form .field{color:rgba(247,246,241,.75);}
.senator-form .field input{background:rgba(247,246,241,.08);border-color:rgba(247,246,241,.25);color:#fff;}
.senator-form .pay-card-head h3{color:#fff;}

/* FOOTER */
.site-footer{background:var(--emerald-950);color:rgba(247,246,241,.8);margin-top:2rem;}
.senator-page + .site-footer,.senator-page ~ .site-footer{margin-top:0;}
.footer-grid{max-width:1180px;margin:0 auto;padding:3.5rem 1.5rem 2rem;display:grid;grid-template-columns:1fr;gap:2.2rem;}
@media(min-width:800px){.footer-grid{grid-template-columns:1.3fr 1fr 1fr;}}
.footer-col p{font-size:.86rem;color:rgba(247,246,241,.65);margin-bottom:.6rem;display:flex;align-items:center;gap:.5rem;}
.footer-col h5{color:#fff;font-family:'Work Sans',sans-serif;font-size:.85rem;letter-spacing:.02em;margin-bottom:1rem;}
.footer-col button{display:block;background:none;border:none;color:rgba(247,246,241,.7);font-size:.86rem;padding:.35rem 0;text-align:left;}
.footer-col button:hover{color:var(--gold-500);}
.social-row{display:flex;gap:.7rem;margin-top:.8rem;}
.social-row a{width:36px;height:36px;border-radius:50%;background:var(--gold-500);color:#fff;display:flex;align-items:center;justify-content:center;transition:background .2s ease, transform .2s ease;}
.social-row a:hover{background:var(--gold-600);transform:translateY(-2px);}
.footer-bottom{border-top:1px solid rgba(247,246,241,.15);text-align:center;font-size:.72rem;color:rgba(247,246,241,.5);padding:1.2rem 1.5rem;}

/* CARD HOVER — subtle gold stroke + blurred glow, used across every page */
.bento-card:hover,
.leader-card:hover,
.project-card:hover,
.pay-card:hover,
.doc-card:hover,
.manifesto-card:hover{
  border-color:var(--gold-500);
  box-shadow:0 0 0 1px rgba(204,154,61,.4), 0 22px 44px -12px rgba(204,154,61,.35);
  transform:translateY(-3px);
}
.manifesto-card:hover{
  box-shadow:0 0 0 1px rgba(204,154,61,.55), 0 22px 44px -10px rgba(204,154,61,.28);
}

/* TOAST */
.toast-host{position:fixed;bottom:1.6rem;left:50%;transform:translateX(-50%);background:var(--emerald-950);color:#fff;padding:.85rem 1.3rem;border-radius:999px;display:flex;align-items:center;gap:.6rem;font-size:.86rem;box-shadow:0 12px 30px rgba(11,42,32,.35);z-index:100;max-width:90vw;}
.toast-host svg{color:var(--gold-500);flex-shrink:0;}
`;
